  add("hdcf",  (tA ? tA.hdcf_pct : NaN) - (tB ? tB.hdcf_pct : NaN), 4.0, 0.60, "HDCF%", `${((tA&&tA.hdcf_pct||0)*100).toFixed(1)} vs ${((tB&&tB.hdcf_pct||0)*100).toFixed(1)}`);
  add("corsi", (tA ? tA.cf_pct : NaN) - (tB ? tB.cf_pct : NaN),    3.0,  0.50, "CF%",   `${((tA&&tA.cf_pct||0)*100).toFixed(1)} vs ${((tB&&tB.cf_pct||0)*100).toFixed(1)}`);
  add("p60",   (tA ? tA.p60 : NaN) - (tB ? tB.p60 : NaN),          0.35, 0.50, "5v5 P/60", `${(tA&&tA.p60||0).toFixed(2)} vs ${(tB&&tB.p60||0).toFixed(2)}`);
  // INDIVIDUAL CHANCE CREATION (Drew's spec: iXG / Primary Points):
  // 50/50 blend of team 5v5 iXG/60 and primary-points/60 (goals + primary
