// Per-factor clamp: no single factor may contribute more than +/-6 expected
// points before its weight is applied (conservative v1 bound).
function footballClampEdge(pts) {
  return Math.max(-6, Math.min(6, pts));
}
// CFB advanced-stats lookup. CFB_TEAM_ADV = { teams: {...}, lookup: {...} }
