    let rank = null;
    try {
      const ranksListRes = await fetchEspnCoreWithRetry(core.ranks.$ref, env);
      const ranksList = await ranksListRes.json();
      const firstRankRef = ranksList.items?.[0]?.$ref;
      if (firstRankRef) {
        const rankDetailRes = await fetchEspnCoreWithRetry(firstRankRef, env);
        const rankDetail = await rankDetailRes.json();
        rank = rankDetail?.rank?.current ?? null;
      }
    } catch (e) {
      rank = null;
    }
    let winPct = null;
