function tennisWeatherHoldAdj({ indoor, wind, precip, temp, humidity }) {
  if (indoor) return { adj: 0, note: "indoor \u2014 no outdoor weather; court plays faster (hold bonus applied separately)" };
  let adj = 0;
  const bits = [];
  if (typeof wind === "number" && wind >= 20) {
    adj -= 0.035;
    bits.push(`${wind}mph wind \u2014 toss and first-serve % drop, holding gets harder`);
  } else if (typeof wind === "number" && wind >= 15) {
    adj -= 0.02;
    bits.push(`${wind}mph wind \u2014 serve consistency takes a hit`);
  }
  if (typeof precip === "number" && precip >= 50) {
    adj -= 0.015;
    bits.push(`${precip}% rain chance \u2014 footing and grip`);
  }
  if (typeof temp === "number" && temp >= 85) {
    adj += 0.012;
    bits.push(`${temp}\xB0F heat \u2014 thinner air, higher bounce, holds go up`);
  }
  if (typeof humidity === "number" && humidity >= 70) {
    adj -= 0.012;
    bits.push(`${humidity}% humidity \u2014 ball fluffs up, longer rallies, holds dip`);
  }
  return { adj, note: bits.join("; ") };
}
