function runGolfFieldSimulation(players, trials = 1e4) {
  const roundStdDev = 2.7;
  const wins = new Array(players.length).fill(0);
  for (let t = 0; t < trials; t++) {
    let bestTotal = Infinity;
    let bestIdx = -1;
    for (let i = 0; i < players.length; i++) {
      let total = 0;
      for (let r = 0; r < 4; r++) total += sampleNormal(players[i].scoringAvg, roundStdDev);
      if (total < bestTotal) {
        bestTotal = total;
        bestIdx = i;
      }
    }
    if (bestIdx >= 0) wins[bestIdx]++;
  }
  return players.map((p, i) => ({ name: p.name, winPct: Math.round(wins[i] / trials * 1e4) / 100, real: p.real })).sort((a, b) => b.winPct - a.winPct);
}
