async function fetchPublicStats(env) {
  const empty = { total: 0, win: 0, loss: 0, push: 0, pending: 0, winPct: null, byLeague: {} };
  try {
    if (!env.AIRTABLE_API_KEY) return empty;
    const baseId = airtableBaseIdForProvider(env, "gemini");
    const tableId = airtableBetsTableId(env);
    let records = [];
    let offset = null;
    const maxPages = 40;
    let pageCount = 0;
    do {
      const queryParams = { pageSize: "100" };
      if (offset) queryParams.offset = offset;
      const params = new URLSearchParams(queryParams);
      ["League", "Result"].forEach((f) => params.append("fields[]", f));
      const url = `https://api.airtable.com/v0/${baseId}/${encodeURIComponent(tableId)}?${params.toString()}`;
      const res = await fetch(url, {
        headers: { Authorization: `Bearer ${env.AIRTABLE_API_KEY}` }
      });
      if (!res.ok) {
        console.error(`Public stats fetch page ${pageCount + 1} failed: HTTP ${res.status}`);
        break;
      }
      const data = await res.json();
      records.push(...data.records || []);
      offset = data.offset;
      pageCount++;
    } while (offset && pageCount < maxPages);
    const stats = { total: records.length, win: 0, loss: 0, push: 0, pending: 0, winPct: null, byLeague: {} };
    for (const r of records) {
      const league = r.fields["League"] || "Other";
      const result = (r.fields["Result"] || "Pending").toLowerCase();
      if (!stats.byLeague[league]) stats.byLeague[league] = { win: 0, loss: 0, push: 0, pending: 0 };
      if (result === "win") {
        stats.win++;
        stats.byLeague[league].win++;
      } else if (result === "loss") {
        stats.loss++;
        stats.byLeague[league].loss++;
      } else if (result === "push") {
        stats.push++;
        stats.byLeague[league].push++;
      } else {
        stats.pending++;
        stats.byLeague[league].pending++;
      }
    }
    const graded = stats.win + stats.loss;
    stats.winPct = graded > 0 ? Math.round(stats.win / graded * 100) : null;
    return stats;
  } catch (err) {
    console.error("Public stats fetch failed:", err.message);
    return empty;
  }
}
