async function fetchRecentPicks(env, limit = 10) {
  try {
    if (!env.AIRTABLE_API_KEY) return [];
    const baseId = airtableBaseIdForProvider(env, "gemini");
    const tableId = airtableBetsTableId(env);
    const params = new URLSearchParams({
      pageSize: String(limit),
      "sort[0][field]": "Placed Date",
      "sort[0][direction]": "desc"
    });
    ["Bet Label", "Picked Winner", "Confidence %", "Result"].forEach((f) => params.append("fields[]", f));
    const url = `https://api.airtable.com/v0/${baseId}/${encodeURIComponent(tableId)}?${params.toString()}`;
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${env.AIRTABLE_API_KEY}` }
    });
    if (!res.ok) {
      console.error(`Recent picks fetch failed: HTTP ${res.status}`);
      return [];
    }
    const data = await res.json();
    const records = data.records || [];
    return records.slice(0, limit).map((r) => {
      const f = r.fields || {};
      return {
        label: f["Bet Label"] || "\u2014",
        winner: f["Picked Winner"] || "\u2014",
        confidence: f["Confidence %"] != null ? Math.round(f["Confidence %"] * 100) : null,
        result: f["Result"] || "Pending"
      };
    });
  } catch (err) {
    console.error("Recent picks fetch failed:", err.message);
    return [];
  }
}
