function isParlayLandingHost(hostname) {
  const h = String(hostname || "").toLowerCase();
  return h === "parlaykings.net" || h.endsWith(".parlaykings.net") || h === "parlaykings.app" || h.endsWith(".parlaykings.app");
}

// The page was authored against ai.grimaldi.tv absolute links; on the
// parlaykings.net origin every app path (login, buy, stats, the SSO
// handoff) exists on this same Worker, so serve those links same-host.
function landingHtmlForHost() {
  return LANDING_HTML.split("https://ai.grimaldi.tv/").join("/");
}

function landingEtToday() {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Detroit", year: "numeric", month: "2-digit", day: "2-digit"
  }).formatToParts(new Date());
  const g = (t) => parts.find((p) => p.type === t).value;
  return `${g("year")}-${g("month")}-${g("day")}`;
}

function landingLongLabel(ymd) {
  const d = new Date(`${ymd}T12:00:00Z`);
  return new Intl.DateTimeFormat("en-US", {
    timeZone: "UTC", weekday: "long", year: "numeric", month: "long", day: "numeric"
  }).format(d);
}

function landingAddDays(ymd, n) {
  const d = new Date(`${ymd}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

function landingConfPct(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.round(n <= 1.5 ? n * 100 : n);
}

function landingResultOf(f) {
  const r = String(f["Result"] || "").trim();
  return r === "Win" || r === "Loss" || r === "Push" ? r : "Pending";
}

function buildLandingPayload(records) {
  const today = landingEtToday();
  const winStart = landingAddDays(today, -29);
  const bandStart = landingAddDays(today, -30);
  const bandEnd = landingAddDays(today, -1);

  let last30 = { wins: 0, losses: 0, pushes: 0, pending: 0, total: 0 };
  let season = { wins: 0, losses: 0, pushes: 0, pending: 0, total: 0 };
  const bandWL = new Map();
  const byDay = new Map();
  const picksByDate = new Map();
  let dataThrough = "";
  let latestGraded = "";

  for (const rec of records || []) {
    const f = (rec && rec.fields) || {};
    const r = landingResultOf(f);
    season.total++;
    if (r === "Win") season.wins++;
    else if (r === "Loss") season.losses++;
    else if (r === "Push") season.pushes++;
    else season.pending++;
    const ed = String(f["Event Date"] || "").slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(ed)) continue;
    if (ed > dataThrough && ed <= today) dataThrough = ed;
    if ((r === "Win" || r === "Loss") && ed > latestGraded && ed <= today) latestGraded = ed;

    if (ed >= winStart && ed <= today) {
      last30.total++;
      if (r === "Win") last30.wins++;
      else if (r === "Loss") last30.losses++;
      else if (r === "Push") last30.pushes++;
      else last30.pending++;
    }
    if (r === "Win" || r === "Loss") {
      const day = byDay.get(ed) || [0, 0];
      if (r === "Win") day[0]++; else day[1]++;
      byDay.set(ed, day);
      if (ed >= bandStart && ed <= bandEnd) {
        const c = landingConfPct(f["Confidence %"]);
        if (c !== null) {
          const band = Math.min(90, Math.floor(c / 10) * 10);
          const b = bandWL.get(band) || [0, 0];
          if (r === "Win") b[0]++; else b[1]++;
          bandWL.set(band, b);
        }
      }
    }
    if (ed <= today) {
      const arr = picksByDate.get(ed) || [];
      arr.push({
        league: String(f["League"] || ""),
        matchup: String(f["Bet Label"] || ""),
        pick: String(f["Picked Winner"] || ""),
        confidence: landingConfPct(f["Confidence %"]),
        result: r
      });
      picksByDate.set(ed, arr);
    }
  }
  const todayPicks = picksByDate.get(today) || [];

  let bw = 0, bl = 0;
  for (const [w, l] of bandWL.values()) { bw += w; bl += l; }
  const overallBandRate = bw + bl > 0 ? bw / (bw + bl) : 0;
  const bandRate = (c) => {
    if (c === null) return -1;
    const band = Math.min(90, Math.floor(c / 10) * 10);
    const b = bandWL.get(band);
    if (!b || b[0] + b[1] < 20) return overallBandRate;
    return b[0] / (b[0] + b[1]);
  };
  const rankDay = (picks) => picks.slice().sort((a, b) => {
    const d = bandRate(b.confidence) - bandRate(a.confidence);
    if (d !== 0) return d;
    return (b.confidence || 0) - (a.confidence || 0);
  });
  let boardDate = todayPicks.length ? today : "";
  if (!boardDate) {
    for (const d of picksByDate.keys()) if (d > boardDate) boardDate = d;
  }
  const boardPicks = boardDate ? picksByDate.get(boardDate) || [] : [];
  const ranked = rankDay(boardPicks);
  const freePicks = ranked.slice(0, 3).map((p) => ({
    league: p.league, matchup: p.matchup, pick: p.pick, confidence: p.confidence
  }));
  const freeSet = new Set(ranked.slice(0, 3));
  const slate = ranked.filter((p) => !freeSet.has(p)).slice(0, 24).map((p) => ({
    league: p.league, matchup: p.matchup
  }));

  const daily = [...byDay.entries()]
    .filter(([d]) => d <= today)
    .sort((a, b) => (a[0] < b[0] ? -1 : 1))
    .slice(-14)
    .map(([date, [w, l]]) => ({ date, wins: w, losses: l, pct: Math.round((100 * w) / (w + l)) }));

  const decided30 = last30.wins + last30.losses;
  const decidedSeason = season.wins + season.losses;
  return {
    ok: true,
    generatedAt: new Date().toISOString(),
    today,
    todayLabel: landingLongLabel(today),
    todayCount: todayPicks.length,
    boardDate,
    boardLabel: boardDate ? landingLongLabel(boardDate) : "",
    boardIsToday: boardDate === today,
    boardCount: boardPicks.length,
    freePicks,
    slate,
    slateTotal: Math.max(0, boardPicks.length - freePicks.length),
    last30: {
      ...last30,
      decided: decided30,
      winRate: decided30 > 0 ? Math.round((1000 * last30.wins) / decided30) / 10 : null
    },
    season: {
      ...season,
      decided: decidedSeason,
      winRate: decidedSeason > 0 ? Math.round((1000 * season.wins) / decidedSeason) / 10 : null
    },
    daily,
    dataThrough,
    dataThroughLabel: dataThrough ? landingLongLabel(dataThrough) : "",
    latestGraded,
    fullRecordUrl: "https://ai.grimaldi.tv/stats"
  };
}

async function handleBoardPage(request, env, session, url) {
  if (!session) {
    return new Response(null, { status: 302, headers: { Location: `/login?redirect=${encodeURIComponent(url.pathname + url.search)}` } });
  }
  const bettor = session.bettorRecordId ? await getBettorRecord(env, session.bettorRecordId) : null;
  const fullAccess = hasSportsSiteAccess(bettor);
  const records = await loadBetsReplica(env);
  const base = {
    hostname: url.hostname,
    username: session.username || "",
    isAdmin: isSlateAdmin(session),
    fullAccess
  };
  if (!Array.isArray(records)) {
    return new Response(boardRenderHtml({ ...base, unavailable: true, boardDate: "", boardIsToday: false, visible: [], locked: [], record: null }), {
      headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" }
    });
  }
  const today = todayET();
  const byDate = new Map();
  for (const r of records) {
    const ed = boardDateKey((r && r.fields) || {});
    if (!ed || ed > today) continue;
    const arr = byDate.get(ed) || [];
    arr.push(boardPickFromRecord(r));
    byDate.set(ed, arr);
  }
  const boardDate = boardChooseDate([...byDate.keys()].sort().reverse(), today);
  const bandRates = boardBandRates(records, today);
  const dayPicks = boardDate ? byDate.get(boardDate) || [] : [];
  const gated = boardDate
    ? boardVisiblePicks(dayPicks, fullAccess, bandRates)
    : { visible: [], locked: [] };
  // League views (?league=NBA) narrow the ALREADY-GATED lists — the
  // filter runs after boardVisiblePicks, never before it.
  const leagueParam = (url.searchParams.get("league") || "").trim();
  const dayLeagues = [...new Set(dayPicks.map((p) => String(p.league || "")).filter(Boolean))];
  const leagueFilter = leagueParam && dayLeagues.some((lg) => lg.toUpperCase() === leagueParam.toUpperCase())
    ? dayLeagues.find((lg) => lg.toUpperCase() === leagueParam.toUpperCase())
    : "";
  const { visible, locked } = boardFilterByLeague(gated.visible, gated.locked, leagueFilter);
  return new Response(boardRenderHtml({
    ...base,
    boardDate,
    boardIsToday: boardDate === today,
    visible,
    locked,
    leagues: dayLeagues,
    leagueFilter,
    record: boardSeasonRecord(records)
  }), {
    headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" }
  });
}

async function getSession(request, env) {
  if (!env.SESSION_SECRET) return null;
  const token = getCookie(request, SESSION_COOKIE_NAME);
  if (token) {
    const verified = await verifySessionToken(token, env);
    if (verified) return verified;
  }
  const premium = getCookie(request, "samPremiumAccess");
  const identifier = getCookie(request, "grimaldi_sub") || getCookie(request, "dgp_subscriber_email");
  if (premium === "yes" && identifier) {
    const bettor = await findBettorByUsername(env, identifier);
    if (bettor && !bettor.error) return { username: bettor.username || identifier, bettorRecordId: bettor.id };
  }
  return null;
}
