async function updateCalibrationBias(env, provider, league, predictedWinPct, outcome) {
  try {
    if (!env.SUPABASE_SERVICE_ROLE_KEY || !league || outcome === "push") return;
    const predictedProb = Math.max(0.01, Math.min(0.99, predictedWinPct / 100));
    const actual = outcome === "win" ? 1 : 0;
    const delta = CALIBRATION_LEARNING_RATE * 100 * (actual - predictedProb);
    const getUrl = `${supabaseUrl(env)}/rest/v1/sam_calibration?provider=eq.${encodeURIComponent(provider)}&league=eq.${encodeURIComponent(league)}&select=bias,n_graded,wins,losses,pushes,updated_at&limit=1`;
    const getRes = await fetch(getUrl, { headers: supabaseHeaders(env) });
    const existingRows = getRes.ok ? await getRes.json() : [];
    const existing = existingRows?.[0];
    // Fresh start on stale rows: a pre-restore row is treated as nonexistent,
    // so the new learner never inherits the old version's wrong-scale values.
    const stale = isStaleCalibrationRow(existing);
    const currentBias = stale ? 0 : (Number(existing.bias) || 0);
    const nGraded = stale ? 1 : (existing.n_graded || 0) + 1;
    const wins = (stale ? 0 : (existing.wins || 0)) + (outcome === "win" ? 1 : 0);
    const losses = (stale ? 0 : (existing.losses || 0)) + (outcome === "loss" ? 1 : 0);
    // SYMMETRIC (since 2026-10-13): the bias may go negative (shave a league
    // whose stated confidence overshoots its hit rate) or positive (raise a
    // league whose stated confidence undershoots it), clamped to ±15.
    const newBias = Math.max(-CALIBRATION_MAX_BIAS, Math.min(CALIBRATION_MAX_BIAS, currentBias + delta));
    const upsertUrl = `${supabaseUrl(env)}/rest/v1/sam_calibration`;
    await fetch(upsertUrl, {
      method: "POST",
      headers: supabaseHeaders(env, { "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" }),
      body: JSON.stringify({
        provider,
        league,
        bias: Math.round(newBias * 100) / 100,
        n_graded: nGraded,
        wins,
        losses,
        pushes: stale ? 0 : (existing?.pushes || 0),
        updated_at: new Date().toISOString()
      })
    });
  } catch (err) {
    console.error(`updateCalibrationBias failed (${provider}/${league}):`, err.message);
  }
}
