async function backfillCalibrationFromAirtable(env) {
  if (!env.AIRTABLE_API_KEY) return [];
  const tableId = airtableBetsTableId(env);
  let allRecords = [];
  for (const t of airtableProviderTargets(env)) {
    let offset;
    do {
      const params = new URLSearchParams({ filterByFormula: "NOT({Result} = 'Pending')", pageSize: "100" });
      if (offset) params.set("offset", offset);
      ["League", "Result", "Confidence %", "Model Version", "Event Date"].forEach((f) => params.append("fields[]", f));
      const res = await fetch(`https://api.airtable.com/v0/${t.baseId}/${encodeURIComponent(tableId)}?${params.toString()}`, {
        headers: { Authorization: `Bearer ${env.AIRTABLE_API_KEY}` }
      });
      if (!res.ok) break;
      const data = await res.json();
      allRecords = allRecords.concat(data.records || []);
      offset = data.offset;
    } while (offset && allRecords.length < 1e5);
  }
  // NATURAL REPLAY (2026-09-29): the old batch-average seed
  // (bias = 100 * mean(actual - predicted)) did NOT reproduce what organic
  // grading would have produced, and a reseed with it would overwrite the
  // corrected values. This now replays history exactly the way the live
  // grader learns it: one online-update step per graded pick, in
  // (Event Date, createdTime, record id) order, with the same formula,
  // per-pick rounding, and symmetric ±15 clamp as updateCalibrationBias.
  // Learns from every model label, same as the live grader.
  const picks = [];
  for (const r of allRecords) {
    const f = r.fields || {};
    const league = normalizeLeague(f["League"]) || "OTHER";
    const result = (f["Result"] || "").toLowerCase();
    if (result !== "win" && result !== "loss") continue;
    const conf = f["Confidence %"];
    if (typeof conf !== "number") continue;
    picks.push({ league, result, conf, eventDate: f["Event Date"] || "", created: r.createdTime || "", id: r.id });
  }
  picks.sort((a, b) =>
    (a.eventDate < b.eventDate ? -1 : a.eventDate > b.eventDate ? 1 : 0) ||
    (a.created < b.created ? -1 : a.created > b.created ? 1 : 0) ||
    (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const buckets = {};
  for (const p of picks) {
    const b = buckets[p.league] || (buckets[p.league] = { bias: 0, n: 0, wins: 0, losses: 0 });
    const predictedProb = Math.max(0.01, Math.min(0.99, p.conf));
    const actual = p.result === "win" ? 1 : 0;
    const delta = CALIBRATION_LEARNING_RATE * 100 * (actual - predictedProb);
    b.bias = Math.round(Math.max(-CALIBRATION_MAX_BIAS, Math.min(CALIBRATION_MAX_BIAS, b.bias + delta)) * 100) / 100;
    b.n++;
    if (actual) b.wins++; else b.losses++;
  }
  // Only the "meta" provider row is ever read (normalizeProvider maps
  // everything there), so only it is seeded — no dead provider rows.
  const summary = [];
  for (const [league, b] of Object.entries(buckets)) {
    try {
      await fetch(`${supabaseUrl(env)}/rest/v1/sam_calibration`, {
        method: "POST",
        headers: supabaseHeaders(env, { "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" }),
        body: JSON.stringify({
          provider: "meta",
          league,
          bias: b.bias,
          n_graded: b.n,
          wins: b.wins,
          losses: b.losses,
          pushes: 0,
          updated_at: new Date().toISOString()
        })
      });
      summary.push({ provider: "meta", league, n: b.n, wins: b.wins, losses: b.losses, bias: b.bias });
    } catch (err) {
      console.error(`Backfill upsert failed (meta/${league}):`, err.message);
    }
  }
  return summary;
}
