async function fetchAllFeedbackRecords(env, tableId) {
  const baseId = "appgyFqsQ6hGVNneI";
  const records = [];
  let offset = null;
  do {
    const params = new URLSearchParams({ "sort[0][field]": "Submitted At", "sort[0][direction]": "desc", pageSize: "100" });
    if (offset) params.set("offset", offset);
    const res = await fetch(`https://api.airtable.com/v0/${baseId}/${tableId}?${params.toString()}`, {
      headers: { Authorization: `Bearer ${env.AIRTABLE_API_KEY}` }
    });
    if (!res.ok) break;
    const data = await res.json();
    records.push(...data.records || []);
    offset = data.offset || null;
  } while (offset);
  return records;
}
