function feedbackCardHtml(record, rating) {
  const f = record.fields || {};
  const badge = rating === "up" ? `<span class="fb-badge fb-up">\u{1F44D} UP</span>` : `<span class="fb-badge fb-down">\u{1F44E} DOWN</span>`;
  const when = f["Submitted At"] ? new Date(f["Submitted At"]).toLocaleString("en-US", { timeZone: "America/New_York", dateStyle: "medium", timeStyle: "short" }) : "unknown time";
  const reasonHtml = rating === "down" && f["Reason"] ? `<div class="fb-reason">"${escapeHtml(f["Reason"])}"</div>` : rating === "down" ? `<div class="fb-reason fb-reason-empty">No reason given</div>` : "";
  return `
    <div class="fb-card" data-rating="${rating}">
      <div class="fb-card-head">
        ${badge}
        <span class="fb-meta">${escapeHtml(f["Username"] || "Guest")} \xB7 ${escapeHtml(f["Provider"] || "unknown")} \xB7 ${escapeHtml(f["Version"] || "")} \xB7 ${when}</span>
      </div>
      ${reasonHtml}
      <div class="fb-question"><span class="fb-label">Q:</span> ${escapeHtml(f["Question"] || "(unknown)")}</div>
      <div class="fb-response-wrap">
        <div class="fb-label">Response:</div>
        <div class="fb-response">${escapeHtml(f["Response"] || "")}</div>
      </div>
    </div>`;
}
