async function clearPendingMLBBets(env) {
  if (!env.AIRTABLE_API_KEY) return { deletedCount: 0, error: "AIRTABLE_API_KEY not set" };
  const bases = airtableProviderTargets(env).map((t) => t.baseId);
  const tableId = airtableBetsTableId(env);
  let totalDeleted = 0;
  const deletedRecords = [];
  for (const baseId of bases) {
    const url = `https://api.airtable.com/v0/${baseId}/${encodeURIComponent(tableId)}`;
    let records = [];
    try {
      const params = new URLSearchParams({
        filterByFormula: "AND({Result} = 'Pending', OR(LOWER({League}) = 'mlb', LOWER({League}) = 'baseball', LOWER({League}) = 'ncaa mens baseball'))",
        pageSize: "100"
      });
      const res = await fetch(`${url}?${params.toString()}`, {
        headers: { Authorization: `Bearer ${env.AIRTABLE_API_KEY}` }
      });
      if (res.ok) {
        const data = await res.json();
        records = data.records || [];
      }
    } catch (err) {
      console.error(`Fetch pending MLB bets failed for base ${baseId}:`, err.message);
    }
    for (let i = 0; i < records.length; i += 10) {
      const chunk = records.slice(i, i + 10);
      const delParams = new URLSearchParams();
      chunk.forEach((r) => delParams.append("records[]", r.id));
      try {
        const delRes = await fetch(`${url}?${delParams.toString()}`, {
          method: "DELETE",
          headers: { Authorization: `Bearer ${env.AIRTABLE_API_KEY}` }
        });
        if (delRes.ok) {
          totalDeleted += chunk.length;
          chunk.forEach((r) => deletedRecords.push(r.fields?.["Bet Label"] || r.id));
          await removeBetsReplicaRecords(env, chunk.map((r) => r.id));
        }
      } catch (err) {
        console.error(`Delete pending MLB bets failed for chunk:`, err.message);
      }
    }
  }
  return { deletedCount: totalDeleted, deletedMatchups: deletedRecords };
}
