async function createStripeCheckoutSession(env, { tier, tierConfig, bettorRecordId, customerEmail, successUrl, cancelUrl }) {
  try {
    if (!env.STRIPE_SECRET_KEY) return { url: null, error: "STRIPE_SECRET_KEY not set" };
    const params = new URLSearchParams();
    const isRecurring = !!(tierConfig && tierConfig.recurring);
    params.append("mode", isRecurring ? "subscription" : "payment");
    params.append("line_items[0][price_data][currency]", "usd");
    params.append("line_items[0][price_data][product_data][name]", tierConfig.label);
    params.append("line_items[0][price_data][product_data][description]", "Subscription to the Drew Grimaldi Podcast plus full ParlayKings sports analysis. ParlayKings is not a gambling site: no wagers are taken and no winnings are paid out.");
    params.append("line_items[0][price_data][product_data][tax_code]", "txcd_10000000");
    if (isRecurring) params.append("line_items[0][price_data][recurring][interval]", tierConfig.recurring);
    params.append("line_items[0][price_data][unit_amount]", String(tierConfig.amountCents));
    params.append("line_items[0][quantity]", "1");
    params.append("success_url", successUrl);
    params.append("cancel_url", cancelUrl);
    params.append("allow_promotion_codes", "true");
    params.append("metadata[tier]", tier);
    if (isRecurring) {
      params.append("subscription_data[metadata][tier]", tier);
    } else {
      params.append("payment_intent_data[metadata][tier]", tier);
    }
    if (bettorRecordId) {
      params.append("client_reference_id", bettorRecordId);
      params.append("metadata[bettorRecordId]", bettorRecordId);
      if (isRecurring) {
        params.append("subscription_data[metadata][bettorRecordId]", bettorRecordId);
      } else {
        params.append("payment_intent_data[metadata][bettorRecordId]", bettorRecordId);
      }
    }
    const email = String(customerEmail || "").trim();
    if (email && email.includes("@")) params.append("customer_email", email);
    const res = await fetch("https://api.stripe.com/v1/checkout/sessions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${env.STRIPE_SECRET_KEY}`,
        "Content-Type": "application/x-www-form-urlencoded"
      },
      body: params.toString()
    });
    const responseText = await res.text();
    if (!res.ok) {
      console.error("Stripe checkout session creation failed:", responseText);
      return { url: null, error: responseText };
    }
    const data = JSON.parse(responseText);
    return { url: data.url || null, error: null };
  } catch (err) {
    console.error("createStripeCheckoutSession failed:", err.message);
    return { url: null, error: err.message };
  }
}
