  function renderQueue() {
    const qInput = document.getElementById('input');
    const row = qInput ? qInput.closest('.input-row') : null;
    let box = document.getElementById('msg-queue');
    if (!msgQueue.length) { if (box) box.remove(); return; }
    if (!row) return;
    if (!box) {
      box = document.createElement('div');
      box.id = 'msg-queue';
      row.parentNode.insertBefore(box, row);
    }
    while (box.firstChild) box.removeChild(box.firstChild);
    msgQueue.forEach((q, i) => {
      const item = document.createElement('div');
      item.className = 'queued-msg';
      const num = document.createElement('span');
      num.className = 'qnum';
      num.textContent = String(i + 1);
      const txt = document.createElement('span');
      txt.className = 'qtext';
      txt.textContent = q;
      const rm = document.createElement('button');
      rm.className = 'qrm';
      rm.type = 'button';
      rm.setAttribute('aria-label', 'Remove queued message ' + (i + 1));
      rm.textContent = String.fromCharCode(215);
      rm.onclick = ((idx) => () => { msgQueue.splice(idx, 1); renderQueue(); qInput.focus(); })(i);
      item.appendChild(num);
      item.appendChild(txt);
      item.appendChild(rm);
      box.appendChild(item);
    });
  }

