  async function renderBgJob(j) {
    const d = (j && j.result) || {};
    if (d.paywall) {
      addPaywallMsg(d);
    } else {
      try { if (d.thinking) renderReasoning(d.thinking); } catch (e) {}
      await typeMsg(d.reply || "No response.", j.message, d.provider);
    }
    conversationHistory.push({ user: j.message, reply: d.reply || "", thinking: d.thinking || "" });
    if (conversationHistory.length > 6) conversationHistory = conversationHistory.slice(-6);
    if (d.predictionsLeft != null) updateSpins(d.predictionsLeft);
    document.getElementById("thinking")?.remove();
  }
  function pollBgJobs() {
    fetch("/api/jobs/mine", { headers: { "Cache-Control": "no-store" } }).then(function(res) {
      return res.ok ? res.json() : null;
    }).then(function(data) {
      const jobs = (data && data.jobs) || [];
      let pending = 0;
      const dones = [];
      jobs.forEach(function(j) {
        if (!j || !j.id) return;
        if (j.convoId && j.convoId !== convoId) return;
        if (j.status === "pending" || j.status === "running") { pending++; return; }
        if ((j.status === "done" || j.status === "failed") && Date.now() - (j.doneAt || 0) < BG_FRESH_MS) {
          var _seenLs = null; try { _seenLs = localStorage.getItem("pk_seen_" + j.id); } catch (e) {}
          if (!seenBgJobs[j.id] && !_seenLs) {
            seenBgJobs[j.id] = 1;
            try { localStorage.setItem("pk_seen_" + j.id, "1"); } catch (e) {}
            addMsg("user", j.message);
          }
          var _startedLs = null; try { _startedLs = localStorage.getItem("pk_started_" + j.id); } catch (e) {}
          if (!startedBgJobs[j.id] && !_startedLs) {
            startedBgJobs[j.id] = 1;
            try { localStorage.setItem("pk_started_" + j.id, "1"); } catch (e) {}
            dones.push(j);
          }
        }
      });
      if (pending > 0) {
        bgFirstSeen = Date.now();
        if (!bgThinking && !document.getElementById("thinking")) {
          showThinking();
          bgThinking = true;
        }
      }
      const bgAge = bgFirstSeen > 0 ? Date.now() - bgFirstSeen : 0;
      const settledNow = pending === 0 && dones.length > 0;
      const watching = pending > 0 || (!settledNow && bgFirstSeen > 0 && bgAge < 10 * 60 * 1000);
      (async function() {
        for (const j of dones) {
          try { await renderBgJob(j); } catch (e) {}
          renderedBgJobs[j.id] = 1;
        }
        if (bgThinking && pending === 0 && (dones.length > 0 || (bgFirstSeen > 0 && bgAge > 10 * 60 * 1000))) {
          document.getElementById("thinking")?.remove();
          bgThinking = false;
        }
      })();
      if (watching) {
        if (!bgPollTimer) bgPollTimer = setInterval(pollBgJobs, 4000);
      } else if (bgPollTimer) {
        clearInterval(bgPollTimer);
        bgPollTimer = 0;
      }
    }).catch(function() {});
  }

