  function pickDeepMaleVoice(voices) {
    if (!voices || !voices.length) return null;
    // Ordered by how reliably these read as a deep, authoritative male voice
    // across the browsers/OSes people actually listen on (iOS Safari, macOS,
    // Android Chrome, Windows Edge/Chrome).
    const preferredNames = [
      'Daniel', 'Alex', 'Google UK English Male', 'Microsoft Guy', 'Microsoft David',
      'Fred', 'Arthur', 'Gordon', 'Aaron', 'Google US English Male', 'Rishi'
    ];
    for (const name of preferredNames) {
      const match = voices.find((v) => v.name.toLowerCase().includes(name.toLowerCase()));
      if (match) return match;
    }
    const heuristicMatch = voices.find((v) => /male/i.test(v.name) && !/female/i.test(v.name) && /^en/i.test(v.lang));
    if (heuristicMatch) return heuristicMatch;
    return null;
  }

